static const char *patch(const char *base, const char *from, const char *to) { /* replace the first occurrence; returns T */
    const char *p = strstr(base, from); if (!p) { printf("   (patch target missing: %s)\n", from); strcpy(T, base); return T; }
    size_t pre = (size_t)(p - base); memcpy(T, base, pre); strcpy(T + pre, to); strcpy(T + pre + strlen(to), p + strlen(from)); return T;
}
static int g_lenient;
static int parse_claim(const char *text) { X.lenient = (uint8_t)g_lenient; int rc = x12_parse(&X, text, (uint32_t)strlen(text)); if (rc) { return 1000 + -rc; } return cl_parse(&B, &X); }
static int has(const char *res, const char *line) { size_t n = strlen(line); const char *p = res; while ((p = strstr(p, line))) { if ((p == res || p[-1] == '\n') && p[n] == '\n') { return 1; } p++; } return 0; }
